print("vol_price_corr signal_artifact:", sa)

# Try to load vol_price_corr signal
vp = None
for cand in ['factors/vol_price_corr_20_signal.csv','factors/vol_price_corr_20.json']:
    try:
        if cand.endswith('.csv'):
            df = pd.read_csv(cand); vp = df.pivot(index='date', columns='symbol', values='value'); break
        else:
            dd = json.load(open(cand))
            # maybe has 'signal' key
            if 'signal' in dd: vp = pd.DataFrame(dd['signal']); break
    except Exception as e:
        pass
print("vol_price_corr loaded:", vp is not None, (None if vp is None else vp.shape))

# Pairwise rank correlation on common dates (cross-sectional, per date)
def xs_rank_ic(a_df, b_df):
    common = a_df.index.intersection(b_df.index)
    ics = []
    for dt in common:
        x = a_df.loc[dt].dropna(); y = b_df.loc[dt].dropna()
        idx = x.index.intersection(y.index)
        if len(idx) >= 6:
            xr = x[idx].rank(); yr = y[idx].rank()
            if xr.std()>0 and yr.std()>0:
                ics.append(np.corrcoef(xr, yr)[0,1])
    return np.nanmean(ics), len(ics)

names = list(signals.keys())
if vp is not None:
    signals['vol_price_corr_20'] = vp
    names.append('vol_price_corr_20')

print("\nPairwise cross-sectional rank corr (avg over dates):")
for i in range(len(names)):
    for j in range(i+1, len(names)):
        m, n = xs_rank_ic(signals[names[i]], signals[names[j]])
        print(f"  {names[i]:22s} vs {names[j]:22s}: {m:+.3f} (n={n})")
