    print(f"  last date: {ic_dates[-1][0]}, last IC={ic_dates[-1][1]:+.4f}")


print("=== Recent rank IC (h=10, online period 2026-07-16..2027-02-26) ===")
for f in ["vol_price_corr_20", "dn_mkt_beta_60d", "eurusd_beta_60d", "rate_beta_cn10y_60d"]:
