python << 'EOF'
import json, base64, zlib, io, pandas as pd, numpy as np

def load_signal(f):
    d = json.load(open(f))
    art = d['validation']['signal_artifact']
    if 'base64' in art['format']:
        raw = base64.b64decode(art['data'])
        df = pd.read_csv(io.BytesIO(zlib.decompress(raw)))
        df = df.set_index(df.columns[0]); df.index = pd.to_datetime(df.index)
    else:
        df = pd.DataFrame(art['values'], index=pd.to_datetime(art['dates']), columns=art['assets'])
    return df.sort_index()

sigs = {f.split('/')[-1].replace('.json',''): load_signal(f) for f in
        ['factors/vol_adj_mom_accel_20x60.json','factors/dn_mkt_beta_60d.json','factors/rate_beta_cn10y_60d.json']}

# Pairwise cross-sectional rank correlation of factor signals (overlap)
names = list(sigs)
print('Pairwise signal correlation (spearman, cross-sectional per date, averaged):')
for i in range(len(names)):
    for j in range(i+1,len(names)):
        a,b = sigs[names[i]], sigs[names[j]]
        idx = a.index.intersection(b.index)
        corrs=[]
        for t in idx:
            x=a.loc[t]; y=b.loc[t]
            m = x.notna() & y.notna()
            if m.sum()>=8:
                c = np.corrcoef(x[m].rank(), y[m].rank())[0,1]
                if np.isfinite(c): corrs.append(c)
        print(f'  {names[i]:24s} vs {names[j]:24s}: mean_spearman={np.mean(corrs):+.3f} n={len(corrs)}')

# Turnover from validation
for f in ['factors/vol_adj_mom_accel_20x60.json','factors/dn_mkt_beta_60d.json','factors/rate_beta_cn10y_60d.json']:
    d=json.load(open(f))
    m=d['validation']['metrics']
    print(f"{d['factor_id']:26s} turnover_10d_rank={m['turnover_10d_rank']:.3f} coverage_dates_ge8={m.get('coverage_dates_ge8',0):.3f}")
