def rank_ic(f, h=10, start=None, end=None):
    fwd = PX.shift(-h)/PX - 1; out=[]
    idx = f.index
    if start is None: start = idx.min()
    if end is None: end = idx.max()
    for t in idx[(idx>=start)&(idx<=end)]:
        x=f.loc[t]; y=fwd.loc[t]; m=x.notna()&y.notna()
        if m.sum()>=8:
            ic=x[m].rank().corr(y[m].rank())
            if pd.notna(ic): out.append(ic)
