def rolling_beta(y, x, w=60, min_obs=40):
    out = pd.Series(np.nan, index=y.index)
    yy, xx = y.values, x.values
    for i in range(w-1, len(y)):
        sl = slice(i-w+1, i+1)
        yv, xv = yy[sl], xx[sl]
        m = ~(np.isnan(yv)|np.isnan(xv))
        if m.sum() >= min_obs and np.nanstd(xv[m])>1e-12:
            try:
                out.iloc[i] = np.polyfit(xv[m], yv[m], 1)[0]
            except Exception:
                pass
    return out
sig={}
for c in px.columns:
    sig['dn_mkt_beta_60d_'+c] = rolling_beta(rets[c], downx, 60, 40)
