S=pd.DataFrame(sig)
fwd = px.shift(-10)/px - 1
def rank_ic(fcols, start, end):
    idx = S.index[(S.index>=start)&(S.index<=end)]
    ics=[]
    prefix = fcols[0].rsplit('_',1)[0]+'_'
    cols2 = [c[len(prefix):] for c in fcols]
    for t in idx:
        s = S.loc[t, fcols]
        f = fwd.loc[t, cols2]; f.index = s.index
        m = s.notna() & f.notna()
        if m.sum() >= 8:
            rho,_ = spearmanr(s[m], f[m])
            if not np.isnan(rho): ics.append(rho)
    ics=np.array(ics)
