import json, base64, zlib, io
import pandas as pd, numpy as np, os

def load_signal(fid):
    d = json.load(open(f'factors/{fid}.json'))
    art = d['validation']['signal_artifact']
    fmt = art['format']
    if 'base64:zlib:csv' in fmt:
        raw = base64.b64decode(art['data'])
        txt = zlib.decompress(raw).decode()
        df = pd.read_csv(io.StringIO(txt), index_col=0, parse_dates=True)
        return df
    elif fmt == 'list':
        dates = pd.to_datetime(art['dates'])
        assets = art['assets']
        vals = art['values']
        df = pd.DataFrame(vals, index=dates, columns=assets)
        return df
    else:
        print('unknown format', fmt, art.keys())
        # dump keys
        return None

sigs = {}
for f in ['vol_adj_mom_accel_20x60','dn_mkt_beta_60d','rate_beta_cn10y_60d']:
    df = load_signal(f)
    if df is not None:
        print(f, 'shape', df.shape, 'range', df.dropna(how='all').index[0], '->', df.dropna(how='all').index[-1])
        sigs[f] = df

# Load prices
px = {}
for f in os.listdir('../persistent/stock_data'):
    if f.endswith('.csv'):
        sym = f[:-4]
        p = pd.read_csv(f'../persistent/stock_data/{f}', index_col=0, parse_dates=True)
        if 'close' in p.columns:
            px[sym] = p['close']
        else:
            px[sym] = p.iloc[:,0]
px = pd.DataFrame(px).sort_index()
print('price range:', px.index[0], '->', px.index[-1], 'rows:', len(px))

# Forward 10d returns
fwd = px.shift(-10) / px - 1.0

# Recent IC analysis
for fid, s in sigs.items():
    print(f'\n=== {fid} ===')
    last_valid = s.dropna(how='all').index[-1]
    print('last valid row date:', last_valid)
    # restrict to common date range with prices
    common_dates = s.index.intersection(fwd.index)
    ics = []
    for dt in common_dates[-120:]:
        frow = s.loc[dt]
        rrow = fwd.loc[dt]
        mask = frow.notna() & rrow.notna()
        if mask.sum() >= 8:
            ic = frow[mask].rank().corr(rrow[mask].rank())
            if pd.notna(ic): ics.append((dt, ic))
    if ics:
        arr = np.array([x[1] for x in ics])
        print(f'recent 120d IC: mean={arr.mean():.4f} icir={arr.mean()/arr.std():.3f} hit={(arr>0).mean():.2f} n={len(arr)}')
        print('  last 10 ICs:', [round(x[1],3) for x in ics[-10:]])
        ics30 = [x[1] for x in ics if x[0] >= common_dates[-31]]
        if ics30:
            a30 = np.array(ics30)
            print(f'  last 30d IC: mean={a30.mean():.4f} hit={(a30>0).mean():.2f} n={len(a30)}')

# Cross-sectional correlations
fids = list(sigs.keys())
print('\n=== Factor pairwise cross-sectional correlation (last 60 dates) ===')
common = None
for f in fids:
    if common is None:
        common = sigs[f].copy()
    else:
        common = common.join(sigs[f], lsuffix='_x', rsuffix=f'_{f}')
# rebuild clean
idx = common.index
sub = pd.DataFrame(index=idx)
for f in fids:
    col = [c for c in common.columns if not c.startswith(f+'_') and c == f or c.startswith(f+'_')]
    # find actual column
    if f in common.columns:
        sub[f] = common[f]
    else:
        cands = [c for c in common.columns if c.endswith(f) or c.startswith(f) or f in c]
        if cands:
            sub[f] = common[cands[0]]
recent = sub.dropna(how='all').tail(60)
corrs = {}
for i,a in enumerate(fids):
    for b in fids[i+1:]:
        corrs[(a,b)] = []
        for dt in recent.index:
            row = recent.loc[dt]
            m = row[[a,b]].dropna()
            if len(m) >= 8:
                c = m[a].corr(m[b])
                if pd.notna(c): corrs[(a,b)].append(c)
for k,v in corrs.items():
    if v: print(k, 'mean corr:', round(np.mean(v),3), 'n=', len(v))
