# recent rank IC of the 3 factors: value at t vs forward 10d return
def vol_adj_mom_accel(c, fast=20, slow=60, vol_win=20):
    r=c.pct_change()
    z=(c/c.shift(fast)-1 - (c/c.shift(slow)-1))/r.rolling(vol_win).std()
    return z

def dn_beta(panel, win=60):
    mkt=panel.mean(axis=1)
    dn=mkt.clip(upper=0.0)
    out={}
    for a in panel.columns:
        z=pd.concat([panel[a].rename('y'), dn.rename('x')],axis=1).dropna().tail(win)
        if len(z)>=40 and z.x.var()>1e-14:
            out[a]=z.y.cov(z.x)/z.x.var()
        else:
            out[a]=np.nan
    return pd.Series(out)

def rate_beta(panel, x, win=60):
