import pandas as pd, numpy as np

assets = ['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
base='../persistent/stock_data'
P={}
for a in assets:
    df=pd.read_csv(f'{base}/{a}.csv'); df.columns=[c.strip() for c in df.columns]
    df['date']=pd.to_datetime(df['date']); df=df.sort_values('date').set_index('date')
    P[a]=df['close']
PX=pd.DataFrame(P); PX=PX[PX.index<='2033-11-25']
R=PX.pct_change()

print('Stale check (flat last 8 obs at 2033-11-25):')
for a in assets:
    tail=PX[a].iloc[-8:]
    flat = (tail.diff().dropna().abs()<1e-12).all()
    print(f'  {a:10s} flat={flat}  last={PX[a].iloc[-1]:.4f}')

live = ['SPX','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','US10Y']
panel = R[live].dropna(how='all')

def vama(c, fast=20, slow=60, vw=20):
    r=c.pct_change()
    return (c/c.shift(fast)-1 - (c/c.shift(slow)-1))/r.rolling(vw).std()

facs = {}
facs['vol_adj_mom_accel_20x60'] = panel.apply(lambda c: vama(c))

# rolling dn beta & rate beta via date loop
def rolling_beta_panel(panel, x_series, win=60, min_obs=40):
    out = pd.DataFrame(index=panel.index, columns=panel.columns, dtype=float)
    for i in range(win-1, len(panel)):
        sub = panel.iloc[i-win+1:i+1]
        x = x_series.reindex(sub.index)
        if x.var() <= 1e-14:
            continue
        for a in sub.columns:
            y = sub[a]
            z = pd.concat([y.rename('y'), x.rename('x')], axis=1).dropna()
            if len(z) >= min_obs:
                out.iloc[i][a] = z.y.cov(z.x)/z.x.var()
    return out

mkt = panel.mean(axis=1)
dn_x = mkt.clip(upper=0.0)
facs['dn_mkt_beta_60d'] = rolling_beta_panel(panel, dn_x)
cn10y_r = R['CN10Y']
facs['rate_beta_cn10y_60d'] = rolling_beta_panel(panel, cn10y_r)

fwd10 = panel.shift(-10).rolling(10).sum()

def rank_ic_series(fv, fwd):
    idx = fv.index.intersection(fwd.index)
    out = {}
    for t in idx:
        f = fv.loc[t].dropna()
        r = fwd.loc[t].reindex(f.index).dropna()
        f = f.reindex(r.index)
        if len(f) >= 6 and f.nunique()>1 and r.nunique()>1:
            out[t] = f.rank().corr(r.rank())
    return pd.Series(out)

print('\n=== Recent rank-IC (forward 10d) of each factor ===')
for name, fv in facs.items():
    ic = rank_ic_series(fv, fwd10).dropna()
    if len(ic)==0:
        print(name, 'no IC'); continue
    for lb,label in [(60,'60d'),(120,'120d'),(250,'250d')]:
        seg = ic.iloc[-lb:]
        if len(seg)>10:
            print(f'{name:28s} {label}: mean={seg.mean():+.4f} icir={seg.mean()/seg.std():+.3f} hit={(seg>0).mean():.2f} n={len(seg)}')
    print(f'{"":28s} last5 IC: {[round(x,3) for x in ic.iloc[-5:]]}')
