python - <<'EOF'
import json, zlib, base64, io, csv
import numpy as np

def load_signal(factor_id):
    d = json.load(open(f'factors/{factor_id}.json'))
    art = d['validation']['signal_artifact']
    if art['format'] == 'base64:zlib:csv':
        raw = base64.b64decode(art['data'])
        txt = zlib.decompress(raw).decode()
        rows = list(csv.reader(io.StringIO(txt)))
        hdr = rows[0]
        dates = [r[0] for r in rows[1:]]
        mat = np.full((len(dates), len(hdr)-1), np.nan)
        for i,r in enumerate(rows[1:]):
            for j,x in enumerate(r[1:]):
                if x.strip()!='':
                    try: mat[i,j] = float(x)
                    except: pass
        return dates, hdr[1:], mat
    else:
        raise ValueError(art['format'])

for fid in ['vol_adj_mom_accel_20x60','dn_mkt_beta_60d','rate_beta_cn10y_60d']:
    dates, cols, mat = load_signal(fid)
    print(fid, 'dates:', dates[0], '..', dates[-1], 'shape', mat.shape, 'n_valid:', np.isfinite(mat).sum())
